contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        address originalOwner = c.owner();
        uint originalDepositsCount = c.depositsCount();
        // Ensure c has some balance to withdraw; send Ether via fallback as this contract is the owner.
        c.fallback{value: 1}();
        uint balanceBefore = address(c).balance;

        // Call withdrawAll as a non-owner (this contract is the owner, so use a different address)
        address nonOwner = address(0xdead);
        bool reverted;
        try c.withdrawAll{from: nonOwner}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Non-owner must revert and no state change
        assert(reverted && address(c).balance == balanceBefore && c.owner() == originalOwner && c.depositsCount() == originalDepositsCount);
    }
}

