contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(caller != c.owner(), "caller must be a non-owner");

        uint beforeDeposits = c.depositsCount();
        address beforeOwner = c.owner();
        uint beforeBalance = address(c).balance;

        bool reverted;

        (bool ok1, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        reverted = !ok1;
        if (ok1) {
            assert(true);
            return;
        }

        (bool ok2, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", uint(0)));
        reverted = reverted && !ok2;
        if (ok2) {
            assert(true);
            return;
        }

        (bool ok3, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", address(0), uint(0), bytes("")));
        reverted = reverted && !ok3;

        assert(
            reverted &&
            c.depositsCount() == beforeDeposits &&
            c.owner() == beforeOwner &&
            address(c).balance == beforeBalance
        );
    }

    receive() external payable {}
}

