    function run(address target, uint value, bytes memory data) public payable {
        require(address(this).balance >= value, "insufficient balance");
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && c.owner() == ownerBefore && c.depositsCount() == depositsBefore && address(c).balance >= 0);
    }

    receive() external payable {}
}
